const fs = require('fs');
const hdrs = JSON.parse(fs.readFileSync('/staging/database/salesshipmentheader.json','utf8'));
const rows = hdrs.data || [];
// Paires uniques origin / destination avec nom du destinataire
const seen = new Set();
const pairs = [];
for (const r of rows) {
  const origin = (r.location_code && r.location_code.trim())
    ? r.location_code.trim() + ', France'
    : 'Marseille, France';
  const dest = [r.ship_to_city, r.ship_to_country].filter(Boolean).join(', ');
  const key  = `${origin}||${dest}`;
  if (!seen.has(key) && (r.ship_to_city || r.ship_to_name)) {
    seen.add(key);
    pairs.push({
      origin,
      destination : dest,
      name        : r.ship_to_name || '',
      order_id    : r.shipment_no  || r.no || ''
    });
  }
}
console.log(`[WF-04] ${pairs.length} paires O/D extraites du staging`);
return pairs.map(p => ({ json: p }));

// ── Référentiel statique des adresses de magasins ──────────────────
const MAGASINS = {
  'magasin jaune': '12 Rue de la Gare, 1000 Lausanne',
  'magasin vert' : '5 Avenue des Alpes, 1201 Genève',
  'magasin rouge': '8 Rue du Marché, 2000 Neuchâtel',
  'magasin blanc': '3 Place de la Gare, 1700 Fribourg'
};

const enriched = $input.all().map(item => {
  const nomNorm      = (item.json.name || '').toLowerCase().trim();
  const destExistante = (item.json.destination || '').trim();

  // Règle : garde l'adresse API si non vide, sinon cherche dans le référentiel
  const destination = destExistante !== ''
    ? destExistante
    : (MAGASINS[nomNorm] || null);

  const address_source = destExistante !== ''
    ? 'api'
    : (MAGASINS[nomNorm] ? 'referentiel' : 'inconnu');

  return { json: { ...item.json, destination, address_source } };
});

// Ignorer les paires sans destination résolue (évite des appels Google inutiles)
const valid = enriched.filter(i => i.json.destination && i.json.destination.trim() !== '');
const ignored = enriched.length - valid.length;

console.log(
  `[WF-04] Enrichissement adresses : ${enriched.length} paires → `
  + `${valid.length} valides | `
  + `${enriched.filter(i => i.json.address_source === 'referentiel').length} depuis référentiel | `
  + `${ignored} ignorées (destination nulle)`
);

return valid;

const api  = $input.first().json;
let pair;
try { pair = $('Split — 1 paire à la fois').item.json; } catch(e) { pair = {}; }
const elem   = api?.rows?.[0]?.elements?.[0] || {};
const status = elem.status || 'UNKNOWN';
return [{ json: {
  origin_query        : pair.origin          || '',
  destination_query   : pair.destination     || '',
  origin_address      : api?.origin_addresses?.[0]      || '',
  destination_address : api?.destination_addresses?.[0] || '',
  distance_meters     : status === 'OK' ? (elem.distance?.value || null) : null,
  duration_seconds    : status === 'OK' ? (elem.duration?.value || null) : null,
  element_status      : status,
  api_status          : api?.status || 'UNKNOWN',
  retrieved_at        : new Date().toISOString(),
  order_id            : pair.order_id      || '',
  name                : pair.name          || '',
  address_source      : pair.address_source || 'api'
}}];

const crypto = require('crypto');
const fs     = require('fs');

function readChecksum(key) {
  const file = `/staging/_metadata/checksums/${key}.json`;
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch(e) { return { hash: null }; }
}

function versionedPaths(prefix, filename) {
  const now = new Date();
  const y   = now.getFullYear();
  const m   = String(now.getMonth()+1).padStart(2,'0');
  const d   = String(now.getDate()).padStart(2,'0');
  const hh  = String(now.getHours()).padStart(2,'0');
  const mm  = String(now.getMinutes()).padStart(2,'0');
  const ts  = `${y}${m}${d}_${hh}${mm}`;
  return {
    versioned : `${prefix}/${y}/${m}/${d}/${ts}/${filename}`,
    latest    : `${prefix}/latest/${filename}`,
    timestamp : now.toISOString()
  };
}

const allResults  = $input.all().flatMap(i => i.json.distance_results || [i.json]).filter(Boolean);
const payload     = JSON.stringify({ metadata: { generated_at: new Date().toISOString(), count: allResults.length }, data: allResults });
const buf         = Buffer.from(payload, 'utf8');
const currentHash = crypto.createHash('md5').update(buf).digest('hex');
const { hash: storedHash } = readChecksum('distances');
const paths       = versionedPaths('raw/enrichment/distances', 'distance_matrix.json');

console.log(`[CDC:distances] ${allResults.length} entrées | hash=${currentHash.substr(0,8)}… changé=${currentHash !== storedHash}`);

const binAttach = { data: buf.toString('base64'), mimeType:'application/json', fileName:'distance_matrix.json' };
return [{
  json: {
    currentHash, storedHash,
    hashChanged  : currentHash !== storedHash,
    versionedKey : paths.versioned,
    latestKey    : paths.latest,
    timestamp    : paths.timestamp,
    count        : allResults.length
  },
  binary: { distData: binAttach }
}];

const fs = require('fs');

function saveChecksum(key, hash, meta) {
  const dir = '/staging/_metadata/checksums';
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(`${dir}/${key}.json`,
    JSON.stringify({ hash, updatedAt: new Date().toISOString(), ...meta }, null, 2));
}

const item = $input.first();
// Récupérer le binaire depuis le nœud CDC (perdu après les 2 uploads S3)
const cdcBinary = $('CDC — Hash distances').first().binary;
if (!cdcBinary || !cdcBinary.distData) {
  throw new Error('[WF-04] Binaire distData introuvable dans CDC — Hash distances');
}
const buf = Buffer.from(cdcBinary.distData.data, 'base64');
fs.mkdirSync('/staging/enrichment', { recursive: true });
fs.writeFileSync('/staging/enrichment/distance_matrix.json', buf);
saveChecksum('distances', item.json.currentHash, {
  count: item.json.count, versionedKey: item.json.versionedKey
});
console.log(`[WF-04] ✅ distance_matrix.json stagé (${item.json.count} entrées) → ${item.json.versionedKey}`);
return [{ json: { status:'success', count: item.json.count, versionedKey: item.json.versionedKey } }];

const cdcNode = 'CDC — Hash distances';
const cdcOut = $('CDC — Hash distances').first();
const s3Out = $input.first();
if (!cdcOut.binary || !cdcOut.binary.distData) {
  throw new Error('[WF-04] Binaire distData introuvable dans CDC — Hash distances');
}
return [{ json: { ...s3Out.json }, binary: cdcOut.binary }];

